 function showCoverage(){openDialog('功能覆盖与多维分析范围',detailHeader('已登录核验学习成长中心五组菜单、11个页面，并结合操作手册V1.2。此仓库交付独立数据看板Demo，页面数字全部模拟，未改动业务后台。')+`<div class="detail-stats"><div class="detail-stat">管理视角<strong>5</strong></div><div class="detail-stat">已核验后台页面<strong>11</strong></div><div class="detail-stat">业务专题<strong>5</strong></div><div class="detail-stat">当前版本<strong>V2.0</strong></div></div>`+detailTable([['模块','module'],['功能覆盖','features'],['看板输出','output'],['来源','source']],coverage.map(r=>({module:r[0],features:r[1],output:r[2],source:r[3]})))+`<h3>需要正式接入确认</h3><ul><li>学员主键、企业/区域归属和角色数据权限。</li><li>学习完成与有效时长、考试批次与及格线、首次/最终通过规则。</li><li>等级计算依据、学分与成长值字段、企业等级及降级阈值。</li><li>知识搜索/阅读/收藏/评论、附件状态、协议勾选与首页入口点击事件。</li></ul><div class="notice">手册描述的周期性降级与后台当前“未学习/不合格触发”规则存在差异，第一版以后台当前功能为依据。所有阈值与奖励分值均为演示值。</div>`,'功能范围与依据');}
 function sourceDialog(id){const rows={knowledge:[2,3,4,5,6],courses:[1],exams:[7],growth:[8,9],badges:[10]};if(rows[id]){openDialog(({knowledge:'知识库管理',courses:'课程学习管理',exams:'试题管理',growth:'学员成长值管理',badges:'勋章管理'})[id]+' · 功能映射',detailHeader('此入口说明原模块与新增看板的对应关系。完整后台仍使用你提供的系统；当前演示聚焦数据看板。')+detailTable([['功能','features'],['对应分析','output']],rows[id].map(i=>({features:coverage[i][1],output:coverage[i][2]})))+`<div class="detail-toolbar"><span>可切换到对应分析页查看模拟数据</span><button class="button primary" data-action="source-go" data-target="${{knowledge:'knowledge',courses:'courses',exams:'exams',growth:'growth',badges:'growth'}[id]}">打开分析${icon('arrow')}</button></div>`,'原模块功能映射');}else openDialog('后台导航说明',detailHeader('第一版演示仅包含学习成长中心新增的数据看板。会员管理、素材中心与工作台为现有后台的导航位置示意。')+`<p>请在原后台使用这些业务功能。看板的企业、区域与学员身份筛选是为后续接入预留的分析维度。</p>`);}
 function download(name,rows,columns){const meta=[['导出主题',name],['数据性质','全部为模拟数据'],['开始日期',state.filters.start],['结束日期',state.filters.end],['区域',state.filters.region],['企业',state.filters.organization==='all'?'全部企业':D.organizations.find(o=>o.id===state.filters.organization)?.name],['学员身份',state.filters.identity],['员工部门',state.filters.department],['人员岗位',state.filters.jobRole],[]];const clean=v=>{if(typeof v==='number')return String(v);let t=String(v??'');if(/^[=+\-@\t\r]/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"';};const content='\uFEFF'+[...meta,columns.map(c=>c[0]),...rows.map(r=>columns.map(c=>r[c[1]]??''))].map(row=>row.map(clean).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`${name}-${state.filters.start}-${state.filters.end}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出当前筛选范围的数据（CSV）');}
 function exportTable(){if(!tableModel)return;const cols=tableModel.columns.filter(c=>!['id','rank'].includes(c.key)).map(c=>[c.label,c.key]);download(tableModel.title,filteredTable(),cols);}
