  'region-detail':el=>{const c=perspectives.regions.find(c=>c.id===el.dataset.id);if(c)openGroup(c.name+' · 区域学习分析',c.people,'按人员区域归属汇总，继承当前身份、部门与岗位筛选','区域对比');},
